// Prebuilt Buzz API v1 module. Luke reviews Blaze's HyperFrames edits live in HyperFrames Studio,
// inside Buzz, before anything is rendered. helper.py (HELPER_SOURCE) makes review copies and runs Studio.
export const inject = ["react", "pages", "host", "relay", "agents", "navigation", "browser"];

export const VERSION = "0.3.0";
export const WORK = "";

export function when(seconds) {
  return new Date(seconds * 1000).toLocaleString(undefined, { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
}
// The message Luke sends Blaze: notes from Studio, or the approval for the final render.
export function blazeMessage(kind, job, text) {
  const made = job.copy?.copiedAt ? ` on a copy made ${when(job.copy.copiedAt)}` : "";
  const body = text.trim();
  if (kind === "approve") return [`Approved: the ${job.label} edit as built in ${job.source} (reviewed in HyperFrames Studio${made}). Go ahead with the final render.`, ...(body ? ["", body] : [])].join("\n");
  return [
    `Review notes on the ${job.label} edit.`,
    `Project: ${job.source} (reviewed in HyperFrames Studio${made}). Times are the composition's playback time; paths in Studio's requests are relative to that project. Change edit.json and rebuild rather than editing index.html.`,
    "",
    body,
  ].join("\n");
}

const BECH32 = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
function polymod(values) {
  const G = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  let chk = 1;
  for (const v of values) { const top = chk >>> 25; chk = ((chk & 0x1ffffff) << 5) ^ v; for (let i = 0; i < 5; i++) if ((top >>> i) & 1) chk ^= G[i]; }
  return chk >>> 0;
}
function bits(data, from, to) {
  let acc = 0, count = 0; const out = [];
  for (const v of data) { acc = (acc << from) | v; count += from; while (count >= to) { count -= to; out.push((acc >>> count) & ((1 << to) - 1)); } }
  if (count) out.push((acc << (to - count)) & ((1 << to) - 1));
  return out;
}
// NIP-19 npub for a hex public key, for the visible `[@Blaze](nostr:npub…)` mention.
export function npubEncode(hex) {
  const data = bits(hex.match(/../g).map(b => parseInt(b, 16)), 8, 5);
  const hrp = [..."npub"].map(c => c.charCodeAt(0));
  const mod = polymod([...hrp.map(c => c >> 5), 0, ...hrp.map(c => c & 31), ...data, 0, 0, 0, 0, 0, 0]) ^ 1;
  return "npub1" + [...data, ...[0, 1, 2, 3, 4, 5].map(i => (mod >>> (5 * (5 - i))) & 31)].map(d => BECH32[d]).join("");
}
export function shortName(name) { return (name || "Blaze").split(/\s+[(—–-]/)[0].trim() || "Blaze"; }
export function blazeAgents(agents, viewer) {
  return agents.filter(a => /^blaze\b/i.test(a.name ?? "") && /^[0-9a-f]{64}$/.test(a.pubkey ?? "") && (!viewer || !a.owner || a.owner === viewer))
    .sort((a, b) => Number(/test/i.test(a.name)) - Number(/test/i.test(b.name)) || a.name.localeCompare(b.name));
}
// Conversations Luke shares with a Blaze agent: DMs first, then Solo chats, then channels, newest first.
export function blazeConversations(channels, agents) {
  const found = [];
  for (const agent of agents) for (const channel of channels) {
    if (channel.archived || channel.readOnly || channel.huddle || channel.pending || channel.channelType === "system") continue;
    const direct = channel.channelType === "dm" && (channel.participants ?? []).includes(agent.pubkey);
    if (!direct && !(channel.members ?? []).includes(agent.pubkey)) continue;
    const label = direct ? `Direct message with ${agent.name}` : channel.channelType === "solo" ? `${agent.name} · Solo: ${channel.name}` : `${agent.name} · #${channel.name}`;
    found.push({ key: `${agent.pubkey}:${channel.id}`, agent, channel, label, rank: direct ? 0 : channel.channelType === "solo" ? 1 : 2 });
  }
  return found.sort((a, b) => a.rank - b.rank || (b.channel.lastActivityAt ?? 0) - (a.channel.lastActivityAt ?? 0));
}

// One helper process per plugin lifetime: JSON lines over stdin/stdout, started on first use.
export function createHelper(host, { source = typeof HELPER_SOURCE === "string" ? HELPER_SOURCE : "", root = WORK, extra = [], timeoutMs = 20000 } = {}) {
  let state = Object.freeze({ status: "idle" });
  const listeners = new Set();
  const set = next => { state = Object.freeze(next); for (const listener of listeners) listener(); };
  const pending = new Map();
  let starting, proc, buffer = "", nextId = 1, onReady;
  function receive(chunk) {
    buffer += chunk;
    let index;
    while ((index = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, index);
      buffer = buffer.slice(index + 1);
      let message;
      try { message = JSON.parse(line); } catch { continue; }
      if ("ready" in message) { onReady?.(message); continue; }
      const waiting = pending.get(message.id);
      if (!waiting) continue;
      pending.delete(message.id);
      clearTimeout(waiting.timer);
      if (message.ok) waiting.resolve(message); else waiting.reject(new Error(message.error || "The review helper could not do that"));
    }
  }
  function ensure() {
    if (starting) return starting;
    starting = (async () => {
      if (typeof host?.spawn !== "function") throw new Error("This Buzz cannot start the review helper. Update Buzz, then open Blaze Review again.");
      set({ status: "starting" });
      buffer = "";
      let timer;
      const ready = new Promise((resolve, reject) => {
        onReady = message => { clearTimeout(timer); if (message.ready) resolve(message); else reject(new Error(message.error || "The review helper did not start")); };
        timer = setTimeout(() => reject(new Error("The review helper did not start. Check that Python 3 is installed (python3).")), 10000);
      });
      const started = await host.spawn("helper", { args: [source, root, ...extra], onStdout: receive, onStderr: () => {} });
      proc = started;
      started.exited.then(code => {
        if (proc !== started) return;
        proc = undefined;
        starting = undefined;
        const error = new Error(`The review helper stopped${code === null ? "" : ` (exit ${code})`}. Retry to start it again.`);
        for (const waiting of pending.values()) { clearTimeout(waiting.timer); waiting.reject(error); }
        pending.clear();
        onReady?.({ ready: false, error: error.message });
        set({ status: "error", error: error.message });
      });
      const info = await ready;
      set({ status: "ready", info });
      return info;
    })().catch(error => {
      starting = undefined;
      const stale = proc;
      proc = undefined;
      stale?.kill();
      set({ status: "error", error: error.message || "The review helper did not start" });
      throw error;
    });
    return starting;
  }
  async function request(op, fields = {}, wait = timeoutMs) {
    await ensure();
    const id = nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { if (pending.delete(id)) reject(new Error("The review helper did not answer. Is the drive busy?")); }, wait);
      pending.set(id, { resolve, reject, timer });
      proc.write(JSON.stringify({ id, op, ...fields }) + "\n").catch(error => { if (pending.delete(id)) { clearTimeout(timer); reject(error); } });
    });
  }
  return { ensure, request, stop: () => proc?.kill(), snapshot: () => state, subscribe: listener => { listeners.add(listener); return () => listeners.delete(listener); } };
}

function remembered(key, fallback) { try { return JSON.parse(localStorage.getItem(`bravebrand.blaze-review.${key}`)) ?? fallback; } catch { return fallback; } }
